<?php

namespace App\RoundRobin\Brand;

use Illuminate\Support\ServiceProvider;

/**
 * Round Robin look for FreeScout (inbox.roundrobin.in), through FreeScout's own hooks (registered in config/app.php).
 * public/rr/brand/css/recolor.css (generated by tools/build_recolor.py) swaps FreeScout's blues
 * for --rr-* variables; public/rr/brand/css/brand.css sets them per variant and adds fonts, navbar, login page and motion.
 */
class BrandServiceProvider extends ServiceProvider
{
    const VARIANTS = ['midnight', 'frost'];
    // Bump when public/rr/brand files change: Cloudflare caches static files at the edge.
    const VERSION = '3';

    public function boot()
    {
        $this->mergeConfigFrom(__DIR__.'/Config/config.php', 'rrbrand');
        $base = '/rr/brand/';
        $v = '?v='.self::VERSION;

        \Eventy::addFilter('layout.title.name', function () {
            return config('rrbrand.title');
        });
        \Eventy::addFilter('layout.favicon', function () use ($base, $v) {
            return asset($base.'img/favicon.ico').$v;
        });
        \Eventy::addFilter('layout.header_logo', function () use ($base, $v) {
            return asset($base.'img/ring.svg').$v;
        });
        \Eventy::addFilter('login.banner', function () use ($base, $v) {
            return asset($base.'img/logo-on-white.svg').$v;
        });
        \Eventy::addFilter('layout.theme_color', function () {
            return self::variant() === 'frost' ? '#ffffff' : '#050b18';
        });
        \Eventy::addFilter('footer.text', function () {
            return config('rrbrand.footer');
        });
        \Eventy::addFilter('stylesheets', function ($styles) use ($base) {
            $styles[] = $base.'css/recolor.css';
            $styles[] = $base.'css/brand.css';

            return $styles;
        });
        \Eventy::addFilter('javascripts', function ($scripts) use ($base) {
            $scripts[] = $base.'js/brand.js';

            return $scripts;
        });
        // Fonts are self-hosted and preloaded so text doesn't shift when they arrive.
        \Eventy::addAction('layout.head', function () use ($base, $v) {
            foreach (['inter-latin-wght', 'space-grotesk-latin-wght'] as $font) {
                echo '<link rel="preload" href="'.asset($base.'fonts/'.$font.'.woff2').$v.'" as="font" type="font/woff2" crossorigin>';
            }
            echo '<link rel="apple-touch-icon" href="'.asset($base.'img/apple-touch-icon.png').$v.'">';
            echo '<link rel="icon" type="image/png" sizes="192x192" href="'.asset($base.'img/icon-192.png').$v.'">';
        });
        \Eventy::addAction('body.class', function () {
            echo ' rr-brand rr-'.self::variant();
        });
        // New mailboxes start with the Round Robin email signature instead of FreeScout's "--" default.
        \App\Mailbox::creating(function (\App\Mailbox $mailbox) {
            $sig = trim((string) $mailbox->signature);
            if ($sig === '' || $sig === trim(\App\Mailbox::DEFAULT_SIGNATURE)) {
                $mailbox->signature = self::emailSignature();
            }
        });
    }

    /**
     * Default email signature (Resources/email-signature.html, 2026-11-04). Tables and inline styles only, so FreeScout's
     * signature cleaner keeps it. Images come from cdn.roundrobin.in (R2 bucket roundrobin-cdn, cached by Cloudflare);
     * give a changed image a new -vN file name. The name and company inherit the client's text colour and the grey and
     * blue are mid-tones, so it reads in light and dark mode.
     */
    public static function emailSignature()
    {
        return trim(file_get_contents(__DIR__.'/Resources/email-signature.html'));
    }

    /** Configured look, or the one previewed this session with ?rr_theme=... */
    public static function variant()
    {
        $request = request();
        $pick = $request ? $request->query('rr_theme') : null;
        if (in_array($pick, self::VARIANTS, true) && $request->hasSession()) {
            $request->session()->put('rr_theme', $pick);
        }
        $session = ($request && $request->hasSession()) ? $request->session()->get('rr_theme') : null;

        return in_array($session, self::VARIANTS, true) ? $session : config('rrbrand.variant', 'midnight');
    }

    public function register()
    {
    }
}
